Mã Python bên dưới giữ nguyên bản đã qua 12 kiểm tra tự động ở lượt Kế toán. Lưu nguyên khối vào `TVDL_KT_Phep_thu_du_lieu.py`, dùng Python 3.10+ và chạy `python TVDL_KT_Phep_thu_du_lieu.py schema` để xem chính xác cột cho từng lệnh; `selftest` kiểm dữ liệu giả. Không có kết nối ngân hàng/thuế/hệ thống thật. Các ví dụ trong chương KT chỉ chạy khi đã chuẩn hóa đúng schema; DL-T01–T12 là quy trình nghiệp vụ rộng hơn, không được mô tả thành 12 chương trình tự động hoàn chỉnh.

```python
#!/usr/bin/env python3
"""Sàng lọc ngoại lệ trên CSV cục bộ, không kết luận gian lận.
Python >=3.10; chỉ thư viện chuẩn. Chạy --help hoặc selftest.
Tiền: chuỗi thập phân chuẩn, ví dụ 1250000.50, KHÔNG dấu phân nghìn.
Ngày YYYY-MM-DD; timestamp ISO 8601 có offset, ví dụ 2026-10-28T19:30:00+07:00.
Giữ số tài khoản, điện thoại, mã số thuế dạng chuỗi. CSV một dòng một đối tượng
theo schema; không dùng các dòng chi tiết hóa đơn như các hóa đơn riêng.
Chỉ đọc dữ liệu đầu vào. Kết quả JSON chứa cảnh báo, không phải phát hiện xác nhận.
"""
import argparse
import csv
import json
import math
import re
import sys
import unicodedata
from collections import defaultdict, Counter
from datetime import date, datetime, timedelta
from decimal import Decimal, InvalidOperation
from pathlib import Path
from zoneinfo import ZoneInfo

SCHEMAS = {
    'quality': ['record_id','debit','credit','document_date'],
    'duplicates': ['record_id','vendor_tax_id','invoice_series','invoice_number','invoice_date','amount','currency'],
    'gaps': ['record_id','issuer_id','doc_type','series','document_date','sequence'],
    'master': ['record_id','bank_code','bank_account','phone','address'],
    'benford': ['record_id','amount','currency'],
    'hours': ['record_id','created_at','posted_at','locked_at','creator','approver'],
    'trend': ['record_id','month','segment','currency','revenue','cogs'],
    'split': ['record_id','vendor_id','approver','date','amount','currency'],
    'age': ['record_id','invoice_date','due_date','amount','currency'],
    'allocations': ['record_id','invoice_id','paid_date','amount','currency'],
}

def amount(s):
    value = str(s).strip()
    if not re.fullmatch(r'[+-]?\d+(\.\d+)?', value):
        raise ValueError(f'Số tiền không đúng định dạng chuẩn: {value!r}')
    try:
        n = Decimal(value)
    except InvalidOperation as exc:
        raise ValueError('Số tiền không hợp lệ') from exc
    return n

def day(s):
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', str(s)):
        raise ValueError('Ngày phải có dạng YYYY-MM-DD')
    return date.fromisoformat(s)

def norm(s):
    return re.sub(r'\s+', '', str(s).strip()).upper()

def bank(s):
    # Không ép sang số, không bỏ số 0 đầu; chỉ bỏ khoảng trắng và dấu phân cách thường.
    return re.sub(r'[\s.-]', '', str(s)).upper()

def phone(s):
    p = re.sub(r'\D','',str(s))
    return '0' + p[2:] if p.startswith('84') and len(p) == 11 else p

def address(s):
    t = unicodedata.normalize('NFKD', str(s).lower().replace('đ','d'))
    t = ''.join(c for c in t if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9]+',' ',t).strip()

def read_csv(path, schema):
    with open(path, encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f)
        missing = set(SCHEMAS[schema]) - set(reader.fieldnames or [])
        if missing:
            raise ValueError('Thiếu cột: ' + ', '.join(sorted(missing)))
        rows = list(reader)
    if any(None in r or any(v is None for v in r.values()) for r in rows):
        raise ValueError('CSV sai số cột; kiểm dấu phẩy và dấu ngoặc kép')
    return rows

def unique_ids(rows):
    ids = [r['record_id'].strip() for r in rows]
    if any(not v for v in ids) or len(set(ids)) != len(ids):
        raise ValueError('record_id phải khác rỗng và duy nhất; kiểm cấp độ dữ liệu')

def quality(rows):
    ids = [r['record_id'].strip() for r in rows]
    errors = []
    dr = cr = Decimal(0)
    for i,r in enumerate(rows,1):
        try:
            dr += amount(r['debit']); cr += amount(r['credit']); day(r['document_date'])
        except ValueError as e:
            errors.append({'row':i,'error':str(e)})
    return {'rows':len(rows),'blank_ids':sum(not i for i in ids),
            'duplicate_ids':[k for k,v in Counter(ids).items() if k and v > 1],
            'debit_valid_parsed':str(dr),'credit_valid_parsed':str(cr),
            'difference':None if errors else str(dr-cr),'parse_errors':errors,
            'note':'Chưa đối chiếu báo cáo gốc ngoài file; cân Nợ/Có không chứng minh dữ liệu đầy đủ.'}

def duplicates(rows):
    unique_ids(rows)
    groups = defaultdict(list)
    incomplete = []
    for r in rows:
        d = day(r['invoice_date']); amount(r['amount'])
        num = norm(r['invoice_number'])
        # Chỉ số hóa đơn toàn chữ số được chuẩn hóa 00012 thành 12; bank/tax không ép số.
        num = str(int(num)) if num.isdigit() else num
        fields = [norm(r['vendor_tax_id']),norm(r['invoice_series']),num]
        if any(not x for x in fields):
            incomplete.append(r['record_id']); continue
        key = tuple(fields) + (d.year,)
        groups[key].append(r)
    return {'candidate_groups':[
        {'record_ids':[r['record_id'] for r in g],
         'different_amount_or_currency':len({(amount(r['amount']),norm(r['currency'])) for r in g})>1}
        for g in groups.values() if len(g)>1],
        'incomplete_key_ids':incomplete,
        'note':'Một dòng một header hóa đơn; kiểm thay thế/điều chỉnh và nhập trùng nguồn. Không tự coi đã trả trùng.'}

def gaps(rows):
    unique_ids(rows); grouped = defaultdict(set)
    for r in rows:
        if not re.fullmatch(r'\d+',r['sequence']) or int(r['sequence']) < 1:
            raise ValueError('sequence phải là số nguyên dương')
        key = (norm(r['issuer_id']),norm(r['doc_type']),norm(r['series']),day(r['document_date']).year)
        if not all(key[:3]): raise ValueError('Thiếu issuer/doc_type/series')
        grouped[key].add(int(r['sequence']))
    result=[]
    for key,seq in grouped.items():
        seq=sorted(seq)
        for a,b in zip(seq,seq[1:]):
            if b>a+1:
                result.append({'group':key,'missing_from':a+1,'missing_to':b-1,'count':b-a-1})
    return {'internal_gaps':result,'note':'Chỉ tìm khoảng trống nội bộ trong cùng dãy. Giữ cả chứng từ hủy; cần danh mục đầy đủ và quy tắc đánh số. Không suy vi phạm từ khoảng trống.'}

def master(vendors,employees):
    unique_ids(vendors); unique_ids(employees)
    transforms = {
        'bank': lambda r: (norm(r['bank_code']),bank(r['bank_account'])) if norm(r['bank_code']) and bank(r['bank_account']) else None,
        'phone': lambda r: phone(r['phone']) or None,
        'address': lambda r: address(r['address']) if len(address(r['address'])) >= 12 else None,
    }
    matches=[]
    for field,fn in transforms.items():
        index=defaultdict(list)
        for e in employees:
            k=fn(e)
            if k: index[k].append(e['record_id'])
        for v in vendors:
            k=fn(v)
            if k:
                for emp in index.get(k,[]):
                    matches.append({'vendor_id':v['record_id'],'employee_id':emp,'matched_field':field})
    return {'candidates':matches,'note':'Không xuất STK/SĐT/địa chỉ thô. Trùng dữ liệu không chứng minh quan hệ lợi ích; số chung/văn phòng chung/ủy quyền có thể hợp lệ. Chỉ xử lý dữ liệu có căn cứ hợp pháp.'}

def benford(rows):
    unique_ids(rows); groups=defaultdict(list); excluded=[]
    for r in rows:
        n=amount(r['amount']); c=norm(r['currency'])
        if not c: raise ValueError('Thiếu currency; không được gộp các đồng tiền')
        if n<=0: excluded.append(r['record_id']); continue
        groups[c].append(n)
    result=[]
    for c,values in groups.items():
        n=len(values); counts=Counter(int(format(x,'f').replace('.','').lstrip('0')[0]) for x in values)
        observed=[counts[i]/n for i in range(1,10)]
        expected=[math.log10(1+1/i) for i in range(1,10)]
        spans_orders=max(values).adjusted()-min(values).adjusted()
        result.append({'currency':c,'n':n,'orders_span':spans_orders,
                       'planning_screen_only':n>=100 and spans_orders>=2,
                       'digits':[{'digit':i,'observed':observed[i-1],'expected':expected[i-1]} for i in range(1,10)],
                       'mad_descriptive':sum(abs(o-e) for o,e in zip(observed,expected))/9})
    return {'groups':result,'nonpositive_excluded_ids':excluded,
            'note':'Ngưỡng 100 và 2 bậc độ lớn chỉ là sàng lọc đề xuất, không bảo đảm phù hợp. Không dùng số định danh, giá niêm yết cố định, dữ liệu bị cắt ngưỡng. Không kiểm định gian lận/p-value; MAD chỉ mô tả.'}

def timestamp(s,tz):
    d=datetime.fromisoformat(s.replace('Z','+00:00'))
    if d.tzinfo is None:
        raise ValueError('Timestamp thiếu múi giờ; chuẩn hóa nguồn và ghi offset trước chạy')
    return d.astimezone(ZoneInfo(tz))

def hours(rows,holidays=(),start=8,end=18,tz='Asia/Ho_Chi_Minh'):
    unique_ids(rows)
    if not 0<=start<end<=24: raise ValueError('Chọn khoảng giờ trong ngày 0<=start<end<=24; ca đêm cần lịch ca riêng')
    holidays={day(d) for d in holidays}; out=[]
    for r in rows:
        t=timestamp(r['created_at'],tz); flags=[]
        if t.weekday()>=5: flags.append('weekend')
        if t.date() in holidays: flags.append('holiday')
        if not start<=t.hour<end: flags.append('outside_selected_hours')
        if r['posted_at'] and r['locked_at'] and timestamp(r['posted_at'],tz)>timestamp(r['locked_at'],tz):
            flags.append('posted_after_supplied_lock')
        if norm(r['creator']) and norm(r['creator'])==norm(r['approver']): flags.append('same_creator_approver')
        if flags:out.append({'record_id':r['record_id'],'flags':flags})
    return {'candidates':out,'note':'Lịch nghỉ/giờ là đầu vào, không phải lịch pháp luật tự cập nhật. Khách sạn/trang trại có ca đêm/cuối tuần; kiểm tài khoản dịch vụ, log nhập bù và lần mở khóa được duyệt.'}

def trend(rows):
    unique_ids(rows); groups=defaultdict(lambda:[Decimal(0),Decimal(0)])
    for r in rows:
        if not re.fullmatch(r'\d{4}-\d{2}',r['month']): raise ValueError('month phải YYYY-MM')
        day(r['month']+'-01')
        key=(r['segment'],norm(r['currency']),r['month'])
        if not key[0] or not key[1]: raise ValueError('Thiếu segment/currency')
        groups[key][0]+=amount(r['revenue']);groups[key][1]+=amount(r['cogs'])
    out=[]
    for (segment,c,m),(rev,cost) in sorted(groups.items()):
        d=day(m+'-01');prev=(d-timedelta(days=1)).strftime('%Y-%m');year=f'{d.year-1:04d}-{d.month:02d}'
        prior=groups.get((segment,c,prev)); yoy=groups.get((segment,c,year))
        def change(old):return str((rev-old[0])/abs(old[0])) if old and old[0]!=0 else None
        out.append({'segment':segment,'currency':c,'month':m,'revenue':str(rev),'cogs':str(cost),
                    'gross_margin':str((rev-cost)/rev) if rev>0 else None,
                    'mom_change':change(prior),'yoy_change':change(yoy)})
    return {'rows':out,'note':'Không bù tháng thiếu thành 0. Tỷ lệ khi doanh thu không dương để null. So cùng mùa/cơ cấu hàng; không đặt ngưỡng gian lận tự động.'}

def split(rows,threshold,window_days=3):
    unique_ids(rows);limit=amount(threshold)
    if limit<=0 or window_days<1: raise ValueError('Hạn mức và cửa sổ phải dương')
    grouped=defaultdict(list);out=[]
    for r in rows:
        val=amount(r['amount']);d=day(r['date'])
        key=(r['vendor_id'],r['approver'],norm(r['currency']))
        if not all(key):raise ValueError('Thiếu nhóm vendor/approver/currency')
        if 0<val<limit:grouped[key].append((d,val,r['record_id']))
    for key,items in grouped.items():
        items.sort()
        for i,(d,_,_) in enumerate(items):
            selected=[x for x in items[i:] if 0<=(x[0]-d).days<window_days]
            total=sum((x[1] for x in selected),Decimal(0))
            if len(selected)>1 and total>=limit:
                out.append({'group':key,'record_ids':[x[2] for x in selected],'total':str(total)})
    return {'candidates':out,'note':'Hạn mức quản trị do người chạy nhập, cùng đơn vị tiền; nếu nhiều tiền tệ chạy riêng từng file. Các cửa sổ có thể trùng nhau, không cộng tổng cảnh báo thành thiệt hại. Xác minh cùng nhu cầu mua/hợp đồng.'}

def age(invoices,allocations,as_of):
    unique_ids(invoices);unique_ids(allocations);cut=day(as_of)
    lookup={r['record_id']:r for r in invoices};paid=defaultdict(Decimal);unknown=[]
    for a in allocations:
        d=day(a['paid_date']);val=amount(a['amount'])
        if d>cut:continue
        inv=lookup.get(a['invoice_id'])
        if inv is None:unknown.append(a['record_id']);continue
        if norm(inv['currency'])!=norm(a['currency']):raise ValueError('Phân bổ khác tiền tệ; cần quy đổi có căn cứ trước')
        if d<day(inv['invoice_date']):raise ValueError('Tiền phân bổ trước hóa đơn: tách ứng trước và xác minh trước chạy tuổi nợ')
        paid[a['invoice_id']]+=val
    out=[]
    for r in invoices:
        if day(r['invoice_date'])>cut:continue
        outstanding=amount(r['amount'])-paid[r['record_id']];days=(cut-day(r['due_date'])).days
        bucket='credit_or_overpaid' if outstanding<0 else 'settled' if outstanding==0 else 'not_due' if days<=0 else '1-30' if days<=30 else '31-90' if days<=90 else '91-180' if days<=180 else 'over_180'
        out.append({'record_id':r['record_id'],'currency':norm(r['currency']),'outstanding':str(outstanding),'days_past_due':max(days,0),'bucket':bucket})
    return {'rows':out,'unmatched_allocation_ids':unknown,
            'note':'Chỉ phân bổ đến ngày chốt; tiền sau kỳ không giảm số dư ngày chốt. Credit note/ứng trước/bù trừ cần dữ liệu được xử lý có căn cứ, không tự quy thành tiền đã thu.'}

def selftest():
    import unittest
    class Tests(unittest.TestCase):
        def test_amount_reject_locale(self):
            with self.assertRaises(ValueError):amount('1,000.00')
        def test_duplicate_key(self):
            base=dict(vendor_tax_id='001',invoice_series='A26',invoice_number='00012',invoice_date='2026-01-01',amount='10',currency='VND')
            r=duplicates([dict(base,record_id='1'),dict(base,record_id='2',invoice_number='12',amount='11')])
            self.assertTrue(r['candidate_groups'][0]['different_amount_or_currency'])
        def test_missing_key_not_match(self):
            b=dict(vendor_tax_id='',invoice_series='A',invoice_number='1',invoice_date='2026-01-01',amount='10',currency='VND')
            self.assertEqual(duplicates([dict(b,record_id='1'),dict(b,record_id='2')])['candidate_groups'],[])
        def test_gap_group(self):
            b=dict(issuer_id='X',doc_type='PT',series='A',document_date='2026-01-01')
            x=gaps([dict(b,record_id='1',sequence='1'),dict(b,record_id='2',sequence='3'),dict(b,record_id='3',sequence='2',series='B')])
            self.assertEqual(x['internal_gaps'][0]['missing_from'],2)
        def test_bank_leading_zero_and_blank(self):
            b=dict(bank_code='B1',bank_account='0012',phone='',address='')
            x=master([dict(b,record_id='v')],[dict(b,record_id='e'),dict(b,record_id='e2',bank_account='12')])
            self.assertEqual(x['candidates'],[{'vendor_id':'v','employee_id':'e','matched_field':'bank'}])
        def test_benford_zero_subunit(self):
            r=benford([{'record_id':str(i),'amount':n,'currency':'VND'} for i,n in enumerate(['0','-1','0.009','100'])])
            self.assertEqual(r['groups'][0]['n'],2)
            self.assertAlmostEqual(sum(d['expected'] for d in r['groups'][0]['digits']),1)
        def test_hours_timezone(self):
            b=dict(record_id='j',created_at='2026-10-28T00:00:00Z',posted_at='',locked_at='',creator='a',approver='b')
            self.assertIn('outside_selected_hours',hours([b])['candidates'][0]['flags'])
            b['created_at']='2026-10-28T07:00:00'
            with self.assertRaises(ValueError):hours([b])
        def test_trend_gap_and_zero(self):
            r=trend([dict(record_id='1',month='2026-01',segment='A',currency='VND',revenue='0',cogs='2'),dict(record_id='2',month='2026-03',segment='A',currency='VND',revenue='10',cogs='5')])
            self.assertIsNone(r['rows'][0]['gross_margin']);self.assertIsNone(r['rows'][1]['mom_change'])
        def test_split_currency(self):
            b=dict(vendor_id='v',approver='a',date='2026-01-01',amount='60',currency='VND')
            rows=[dict(b,record_id='1'),dict(b,record_id='2'),dict(b,record_id='3',currency='USD')]
            self.assertEqual(split(rows,'100')['candidates'][0]['record_ids'],['1','2'])
        def test_age_asof(self):
            inv=[dict(record_id='i',invoice_date='2026-01-01',due_date='2026-01-15',amount='100',currency='VND')]
            alloc=[dict(record_id='p1',invoice_id='i',paid_date='2026-01-20',amount='40',currency='VND'),dict(record_id='p2',invoice_id='i',paid_date='2026-02-01',amount='60',currency='VND')]
            self.assertEqual(age(inv,alloc,'2026-01-31')['rows'][0]['outstanding'],'60')
        def test_quality_errors(self):
            r=quality([dict(record_id='1',document_date='2026-01-01',debit='a',credit='0')])
            self.assertIsNone(r['difference']);self.assertEqual(len(r['parse_errors']),1)
        def test_same_amount_different_supplier(self):
            b=dict(invoice_series='A',invoice_number='1',invoice_date='2026-01-01',amount='10',currency='VND')
            self.assertFalse(duplicates([dict(b,record_id='1',vendor_tax_id='A'),dict(b,record_id='2',vendor_tax_id='B')])['candidate_groups'])
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(Tests))
    return 0 if result.wasSuccessful() else 1

def main():
    p=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('test',choices=list(SCHEMAS.keys())[:-1]+['selftest','schema'])
    p.add_argument('--input');p.add_argument('--second');p.add_argument('--output')
    p.add_argument('--as-of');p.add_argument('--threshold');p.add_argument('--window-days',type=int,default=3)
    p.add_argument('--holiday',action='append',default=[])
    p.add_argument('--start',type=int,default=8);p.add_argument('--end',type=int,default=18)
    p.add_argument('--timezone',default='Asia/Ho_Chi_Minh')
    a=p.parse_args()
    if a.test=='selftest':return selftest()
    try:
        if a.output and any(v and Path(a.output).resolve()==Path(v).resolve() for v in (a.input,a.second)):
            raise ValueError('Không được ghi kết quả đè dữ liệu đầu vào')
        if a.output and Path(a.output).exists():raise ValueError('File đầu ra đã tồn tại; chọn tên mới để giữ lịch sử')
        if a.test=='schema':res=SCHEMAS
        else:
            if not a.input:raise ValueError('Thiếu --input')
            rows=read_csv(a.input,a.test)
            if a.test=='master':
                if not a.second:raise ValueError('master cần --second employees.csv')
                res=master(rows,read_csv(a.second,'master'))
            elif a.test=='age':
                if not a.second or not a.as_of:raise ValueError('age cần --second allocations.csv và --as-of YYYY-MM-DD')
                res=age(rows,read_csv(a.second,'allocations'),a.as_of)
            elif a.test=='split':
                if not a.threshold:raise ValueError('split cần --threshold, theo đơn vị tiền của một file')
                if len({norm(r['currency']) for r in rows})>1:raise ValueError('split: tách file một tiền tệ hoặc định nghĩa hạn mức riêng')
                res=split(rows,a.threshold,a.window_days)
            elif a.test=='hours':res=hours(rows,a.holiday,a.start,a.end,a.timezone)
            else:res=globals()[a.test](rows)
        payload=json.dumps({'tool':'TVDL_KT_analytics','version':'1.0','result':res},ensure_ascii=False,indent=2)
        if a.output:Path(a.output).write_text(payload+'\n',encoding='utf-8')
        else:print(payload)
        return 0
    except (ValueError,OSError,KeyError) as exc:
        print('LỖI DỮ LIỆU: '+str(exc),file=sys.stderr);return 2

if __name__=='__main__':
    sys.exit(main())
